class Solution:
    def deleteTreeNodes(self, nodes: int, parent: List[int], value: List[int]) -> int:
        from collections import defaultdict
        ch = defaultdict(list)
        for i in range(1, nodes):
            ch[parent[i]].append(i)

        def dfs(u):
            s, c = value[u], 1
            for v in ch[u]:
                ds, dc = dfs(v)
                s += ds
                c += dc
            return (s, c) if s != 0 else (0, 0)

        return dfs(0)[1]

