class Solution {
public:
    vector<vector<int>> ch;
    vector<int> val;
    pair<long long,int> dfs(int u) {
        long long s = val[u]; int c = 1;
        for (int v : ch[u]) {
            auto r = dfs(v);
            s += r.first; c += r.second;
        }
        if (s == 0) return {0, 0};
        return {s, c};
    }
    int deleteTreeNodes(int nodes, vector<int>& parent, vector<int>& value) {
        ch.assign(nodes, {}); val = value;
        for (int i = 1; i < nodes; i++) ch[parent[i]].push_back(i);
        return dfs(0).second;
    }
};

