class Solution {
    private List<List<Integer>> ch;
    private int[] val;

    public int deleteTreeNodes(int nodes, int[] parent, int[] value) {
        ch = new ArrayList<>();
        for (int i = 0; i < nodes; i++) ch.add(new ArrayList<>());
        for (int i = 1; i < nodes; i++) ch.get(parent[i]).add(i);
        val = value;
        long[] res = dfs(0);
        return (int) res[1];
    }

    private long[] dfs(int u) {
        long s = val[u]; long c = 1;
        for (int v : ch.get(u)) {
            long[] r = dfs(v);
            s += r[0]; c += r[1];
        }
        if (s == 0) return new long[]{0, 0};
        return new long[]{s, c};
    }
}

