class Solution:
    def deleteTreeNodes(self, nodes: int, parent: List[int], value: List[int]) -> int:
        from collections import deque
        ch = [[] for _ in range(nodes)]
        for i in range(1, nodes):
            ch[parent[i]].append(i)
        order = []
        q = deque([0])
        while q:
            u = q.popleft()
            order.append(u)
            for v in ch[u]:
                q.append(v)
        s = value[:]
        c = [1] * nodes
        for u in reversed(order):
            p = parent[u]
            if u == 0:
                continue
            if s[u] != 0:
                s[p] += s[u]
                c[p] += c[u]
        return c[0]

