class Solution {
public:
    int deleteTreeNodes(int nodes, vector<int>& parent, vector<int>& value) {
        vector<vector<int>> ch(nodes);
        for (int i = 1; i < nodes; i++) ch[parent[i]].push_back(i);
        vector<int> order;
        queue<int> q;
        q.push(0);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            order.push_back(u);
            for (int v : ch[u]) q.push(v);
        }
        vector<long long> s(value.begin(), value.end());
        vector<int> c(nodes, 1);
        for (int i = nodes - 1; i > 0; i--) {
            int u = order[i], p = parent[u];
            if (s[u] != 0) { s[p] += s[u]; c[p] += c[u]; }
        }
        return c[0];
    }
};

