class Solution {
    public int deleteTreeNodes(int nodes, int[] parent, int[] value) {
        List<List<Integer>> ch = new ArrayList<>();
        for (int i = 0; i < nodes; i++) ch.add(new ArrayList<>());
        for (int i = 1; i < nodes; i++) ch.get(parent[i]).add(i);
        int[] order = new int[nodes];
        int idx = 0;
        Deque<Integer> q = new ArrayDeque<>();
        q.add(0);
        while (!q.isEmpty()) {
            int u = q.poll();
            order[idx++] = u;
            for (int v : ch.get(u)) q.add(v);
        }
        long[] s = new long[nodes];
        int[] c = new int[nodes];
        for (int i = 0; i < nodes; i++) { s[i] = value[i]; c[i] = 1; }
        for (int i = nodes - 1; i >= 1; i--) {
            int u = order[i], p = parent[u];
            if (s[u] != 0) { s[p] += s[u]; c[p] += c[u]; }
        }
        return c[0];
    }
}

